<?php
declare(strict_types=1);
$bio = $marketingStore->linkBioPresentation(); $catalog = mm_publication_metadata_catalog();
mm_measurement_authorize();
?>
<section class="marketing-card" style="margin-top:22px" data-link-bio-settings><h2>Optional link-in-bio featured image</h2><p>Choose a saved public image. Missing, private or changed assets are omitted when visitors open your links page.</p><form class="marketing-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_link_bio_presentation"><input type="hidden" name="bio_revision" value="<?= velvet_marketing_escape($bio['revision']) ?>"><label>Public featured image<select name="featured_asset_id" aria-label="Public featured image"><option value="">No featured image</option><?php $found = false; foreach ($catalog['images'] as $image): $selected = $image['id'] === $bio['featured_asset_id']; $found = $found || $selected; ?><option value="<?= velvet_marketing_escape($image['id']) ?>" <?= $selected ? 'selected' : '' ?>><?= velvet_marketing_escape($image['title']) ?></option><?php endforeach; ?><?php if (!$found && $bio['featured_asset_id'] !== ''): ?><option selected value="<?= velvet_marketing_escape($bio['featured_asset_id']) ?>">Unavailable saved image — select another or remove</option><?php endif; ?></select></label><label>Image description<input name="featured_alt" maxlength="240" value="<?= velvet_marketing_escape($bio['featured_alt']) ?>"></label><?php if ($catalog['problem'] !== ''): ?><p role="alert"><?= velvet_marketing_escape($catalog['problem']) ?></p><?php endif; ?><button class="marketing-button">Save featured image</button></form></section>
